196.         return;
197.       }
198. 
199.       switch (body.action) {
200.         case 'entriesByFolder': {
201.           const payload = body.params as EntriesByFolderParams;
202.           const { folder, extension, depth } = payload;
203.           const entries = await runOnBranch(git, branch, () =>
