207.                 files.map(file => ({ path: file })),
208.               ),
209.             ),
210.           );
211.           res.json(entries);
212.           break;
213.         }
214.         case 'entriesByFiles': {
215.           const payload = body.params as EntriesByFilesParams;
216.           const entries = await runOnBranch(git, branch, () =>
217.             entriesFromFiles(repoPath, payload.files),
218.           );
219.           res.json(entries);
220.           break;
221.         }
222.         case 'getEntry': {
223.           const payload = body.params as GetEntryParams;
224.           const [entry] = await runOnBranch(git, branch, () =>
225.             entriesFromFiles(repoPath, [{ path: payload.path }]),
226.           );
227.           res.json(entry);
228.           break;
229.         }
230.         case 'unpublishedEntries': {
231.           const cmsBranches = await git
232.             .branchLocal()
233.             .then(result => result.all.filter(b => b.startsWith(`${CMS_BRANCH_PREFIX}/`)));
234.           res.json(cmsBranches.map(contentKeyFromBranch));
235.           break;
236.         }
237.         case 'unpublishedEntry': {
238.           let { id, collection, slug, cmsLabelPrefix } = body.params as UnpublishedEntryParams;
239.           if (id) {
240.             ({ collection, slug } = parseContentKey(id));
241.           }
242.           const contentKey = generateContentKey(collection as string, slug as string);
243.           const cmsBranch = branchFromContentKey(contentKey);
244.           const branchExists = await isBranchExists(git, cmsBranch);
245.           if (branchExists) {
246.             const diffs = await getDiffs(git, branch, cmsBranch);
247.             const label = await git.raw(['config', branchDescription(cmsBranch)]);
248.             const status = label && labelToStatus(label.trim(), cmsLabelPrefix || '');
249.             const updatedAt =
250.               diffs.length >= 0
251.                 ? await runOnBranch(git, cmsBranch, async () => {
252.                     const dates = await Promise.all(
253.                       diffs.map(({ newPath }) => getUpdateDate(repoPath, newPath)),
254.                     );
255.                     return dates.reduce((a, b) => {
256.                       return a > b ? a : b;
257.                     });
258.                   })
259.                 : new Date();
260.             const unpublishedEntry = {
261.               collection,
262.               slug,
263.               status,
264.               diffs,
265.               updatedAt,
266.             };
267.             res.json(unpublishedEntry);
268.           } else {
269.             return res.status(404).json({ message: 'Not Found' });
270.           }
271.           break;
272.         }
273.         case 'unpublishedEntryDataFile': {
274.           const { path, collection, slug } = body.params as UnpublishedEntryDataFileParams;
275.           const contentKey = generateContentKey(collection as string, slug as string);
276.           const cmsBranch = branchFromContentKey(contentKey);
277.           const [entry] = await runOnBranch(git, cmsBranch, () =>
278.             entriesFromFiles(repoPath, [{ path }]),
279.           );
280.           res.json({ data: entry.data });
281.           break;
282.         }
283.         case 'unpublishedEntryMediaFile': {
284.           const { path, collection, slug } = body.params as UnpublishedEntryMediaFileParams;
285.           const contentKey = generateContentKey(collection as string, slug as string);
286.           const cmsBranch = branchFromContentKey(contentKey);
287.           const file = await runOnBranch(git, cmsBranch, () => readMediaFile(repoPath, path));
288.           res.json(file);
289.           break;
290.         }
291.         case 'deleteUnpublishedEntry': {
292.           const { collection, slug } = body.params as DeleteEntryParams;
293.           const contentKey = generateContentKey(collection, slug);
294.           const cmsBranch = branchFromContentKey(contentKey);
295.           const currentBranch = await getCurrentBranch(git);
296.           if (currentBranch === cmsBranch) {
297.             await git.checkoutLocalBranch(branch);
298.           }
299.           await git.branch(['-D', cmsBranch]);
300.           res.json({ message: `deleted branch: ${cmsBranch}` });
301.           break;
302.         }
303.         case 'persistEntry': {
304.           const {
305.             cmsLabelPrefix,
306.             entry,
307.             dataFiles = [entry as DataFile],
308.             assets,
309.             options,
310.           } = body.params as PersistEntryParams;
311. 
312.           if (!options.useWorkflow) {
313.             await runOnBranch(git, branch, async () => {
314.               await commitEntry(git, repoPath, dataFiles, assets, options.commitMessage);
315.             });
316.           } else {
317.             const slug = dataFiles[0].slug;
318.             const collection = options.collectionName as string;
319.             const contentKey = generateContentKey(collection, slug);
320.             const cmsBranch = branchFromContentKey(contentKey);
321.             await runOnBranch(git, branch, async () => {
322.               const branchExists = await isBranchExists(git, cmsBranch);
323.               if (branchExists) {
324.                 await git.checkout(cmsBranch);
325.               } else {
326.                 await git.checkoutLocalBranch(cmsBranch);
327.               }
328.               await rebase(git, branch);
329.               const diffs = await getDiffs(git, branch, cmsBranch);
330.               // delete media files that have been removed from the entry
331.               const toDelete = diffs.filter(
332.                 d => d.binary && !assets.map(a => a.path).includes(d.path),
333.               );
334.               await Promise.all(toDelete.map(f => fs.unlink(path.join(repoPath, f.path))));
335.               await commitEntry(git, repoPath, dataFiles, assets, options.commitMessage);
336. 
337.               // add status for new entries
338.               if (!branchExists) {
339.                 const description = statusToLabel(options.status, cmsLabelPrefix || '');
340.                 await git.addConfig(branchDescription(cmsBranch), description);
341.               }
342.             });
343.           }
344.           res.json({ message: 'entry persisted' });
345.           break;
346.         }
347.         case 'updateUnpublishedEntryStatus': {
348.           const { collection, slug, newStatus, cmsLabelPrefix } =
349.             body.params as UpdateUnpublishedEntryStatusParams;
350.           const contentKey = generateContentKey(collection, slug);
351.           const cmsBranch = branchFromContentKey(contentKey);
352.           const description = statusToLabel(newStatus, cmsLabelPrefix || '');
353.           await git.addConfig(branchDescription(cmsBranch), description);
354.           res.json({ message: `${branch} description was updated to ${description}` });
355.           break;
356.         }
357.         case 'publishUnpublishedEntry': {
358.           const { collection, slug } = body.params as PublishUnpublishedEntryParams;
359.           const contentKey = generateContentKey(collection, slug);
360.           const cmsBranch = branchFromContentKey(contentKey);
361.           await merge(git, cmsBranch, branch);
362.           await git.deleteLocalBranch(cmsBranch);
363.           res.json({ message: `branch ${cmsBranch} merged to ${branch}` });
364.           break;
365.         }
366.         case 'getMedia': {
367.           const { mediaFolder } = body.params as GetMediaParams;
368.           const mediaFiles = await runOnBranch(git, branch, async () => {
369.             const files = await listRepoFiles(repoPath, mediaFolder, '', 1);
370.             const serializedFiles = await Promise.all(
371.               files.map(file => readMediaFile(repoPath, file)),
372.             );
373.             return serializedFiles;
374.           });
375.           res.json(mediaFiles);
376.           break;
377.         }
378.         case 'getMediaFile': {
379.           const { path } = body.params as GetMediaFileParams;
380.           const mediaFile = await runOnBranch(git, branch, () => {
381.             return readMediaFile(repoPath, path);
382.           });
383.           res.json(mediaFile);
384.           break;
385.         }
386.         case 'persistMedia': {
387.           const {
388.             asset,
389.             options: { commitMessage },
390.           } = body.params as PersistMediaParams;
391. 
392.           const file = await runOnBranch(git, branch, async () => {
393.             await writeFile(
394.               path.join(repoPath, asset.path),
395.               Buffer.from(asset.content, asset.encoding),
396.             );
397.             await commit(git, commitMessage);
398.             return readMediaFile(repoPath, asset.path);
399.           });
400.           res.json(file);
401.           break;
402.         }
403.         case 'deleteFile': {
404.           const {
405.             path: filePath,
406.             options: { commitMessage },
407.           } = body.params as DeleteFileParams;
408.           await runOnBranch(git, branch, async () => {
409.             await deleteFile(repoPath, filePath);
410.             await commit(git, commitMessage);
411.           });
412.           res.json({ message: `deleted file ${filePath}` });
413.           break;
414.         }
415.         case 'deleteFiles': {
416.           const {
417.             paths,
418.             options: { commitMessage },
419.           } = body.params as DeleteFilesParams;
420.           await runOnBranch(git, branch, async () => {
421.             await Promise.all(paths.map(filePath => deleteFile(repoPath, filePath)));
422.             await commit(git, commitMessage);
423.           });
424.           res.json({ message: `deleted files ${paths.join(', ')}` });
425.           break;
426.         }
427.         case 'getDeployPreview': {
428.           res.json(null);
429.           break;
430.         }
431.         default: {
432.           const message = `Unknown action ${body.action}`;
433.           res.status(422).json({ error: message });
434.           break;
435.         }
436.       }
437.     } catch (e) {
438.       logger.error(`Error handling ${JSON.stringify(req.body)}: ${e.message}`);
439.       res.status(500).json({ error: 'Unknown error' });
440.     } finally {
441.       release && release();
442.     }
443.   };
444. }
