450. export async function registerMiddleware(app: express.Express, options: Options) {
451.   const { logger } = options;
452.   const repoPath = path.resolve(process.env.GIT_REPO_DIRECTORY || process.cwd());
453.   await validateRepo({ repoPath });
454.   app.post('/api/v1', joi(getSchema({ repoPath })));
455.   app.post('/api/v1', localGitMiddleware({ repoPath, logger }));
456.   logger.info(`Netlify CMS Git Proxy Server configured with ${repoPath}`);
457. }
