     const json = jest.fn();
     const status = jest.fn(() => ({ json }));
     const res: express.Response = { status } as unknown as express.Response;

     const repoPath = '.';

     it("should return error when default branch doesn't exist", async () => {
       git.branchLocal.mockResolvedValue({ all: ['master'] });

       const req = {
